function quotaClassificationOf(ctx) {
    var cls = quotaBreaker.classifyFailure(classifyInterruptedText(ctx.cliErrorMessage, ctx.developmentSummary));
    return (cls && cls.kind === 'quota_exhausted') ? cls : null;
