    try {
        getTracker().postComment(ctx.ticketKey, commentBody);
    } catch (e) { }
    try {
        getTracker().moveToStatus(ctx.ticketKey, ctx.statuses.READY_FOR_DEVELOPMENT);
        console.log('✅ Moved', ctx.ticketKey, 'to Ready For Development for retry');
